package com.gta.launcher.activity;
import android.content.Context;import android.content.SharedPreferences;import android.security.keystore.*;import android.util.Base64;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.nio.charset.StandardCharsets;import java.net.*;import java.io.*;import org.json.JSONObject;import com.gta.game.R;
/** Server session encrypted using a device-only Android Keystore key. */
public final class GoogleSession52 {
 private static final String ALIAS="CidadeGrandeGoogle52";private final SharedPreferences prefs;private final Context context;
 public GoogleSession52(Context c){context=c.getApplicationContext();prefs=context.getSharedPreferences("bcg_google50",0);synchronized(GoogleSession52.class){String old=prefs.getString("session","");if(!old.isEmpty()){try{save(old);}catch(Exception e){}prefs.edit().remove("session").commit();}}}
 private static synchronized SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(!s.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setKeySize(256).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)s.getKey(ALIAS,null);}
 private static String b64(byte[] b){return Base64.encodeToString(b,Base64.NO_WRAP);}
 public void save(String token)throws Exception{if(!token.matches("[A-Za-z0-9_-]{32,128}"))throw new IOException("Sessão inválida");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());c.updateAAD(ALIAS.getBytes(StandardCharsets.UTF_8));String encrypted=b64(c.getIV())+"."+b64(c.doFinal(token.getBytes(StandardCharsets.UTF_8)));if(!prefs.edit().putString("encrypted52",encrypted).remove("session").commit())throw new IOException("Falha ao salvar sessão");}
 public String load(){try{String[] parts=prefs.getString("encrypted52","").split("\\.");if(parts.length!=2)return "";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],0)));c.updateAAD(ALIAS.getBytes(StandardCharsets.UTF_8));return new String(c.doFinal(Base64.decode(parts[1],0)),StandardCharsets.UTF_8);}catch(Exception e){clear();return "";}}
 public void clear(){prefs.edit().remove("session").remove("encrypted52").apply();}
 public JSONObject request(String path,JSONObject body)throws Exception{String token=load();if(token.isEmpty())throw new IOException("Entre novamente com Google");String origin=context.getString(R.string.google_auth50_url);if(!origin.startsWith("https://"))throw new IOException("HTTPS necessário");HttpURLConnection c=(HttpURLConnection)new URL(origin+path).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Accept","application/json");try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}if(c.getResponseCode()!=200)throw new IOException("Autorização indisponível");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){if(out.size()+n>32768)throw new IOException("Resposta excessiva");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
}
